import{x as C,j as e,s as l,dq as D,ab as y,dr as g,ds as v,dt as f,F as x,C as c,R as b,a as j,du as E,H as M,O as S,b as i,c as A,dv as T,D as d,dw as $,d as q,e as I,M as U,I as F,f as P,G as z}from"./index-DScQgT8M.js";import{g as w}from"./guildCopy-CeuiaadK.js";import"./vendor-DDxydHEc.js";function W({isOpen:_,onClose:u,language:r="en-US"}){const R=r==="pt-BR",o=(t,n)=>R?t:n,[k,N]=C.useState(null),s=D,[,,m]=M,h=Math.round(z*c),p=I.length,a={...l,margin:0},O=[{id:"evolve",title:o("Como seu Soulmon evolui","How it evolves"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:a,children:o("Dia completo = você cumpriu a meta do dia e a energia do seu Soulmon fechou cheia. A meta é o que você cadastrou, até o requisito do estágio.","A complete day = you met your daily goal and its energy ended full. The goal is what you registered, capped at your stage requirement.")}),e.jsx("p",{style:a,children:o(`Rookie→Champion pede ${s.rookie.required} dias completos; Champion→Ultimate ${s.champion.required}; Ultimate→Mega ${s.ultimate.required}; Mega→Ultra ${s.mega.required}.`,`Rookie→Champion needs ${s.rookie.required} complete days; Champion→Ultimate ${s.champion.required}; Ultimate→Mega ${s.ultimate.required}; Mega→Ultra ${s.mega.required}.`)}),e.jsx("p",{style:a,children:o(`O Ultra tem dois caminhos: ${y} dias completos como mega, ou conhecer os três galhos. Nenhum é melhor, e nenhum pede que você degenere.`,`The Ultra has two paths: ${y} complete days as a mega, or knowing all three branches. Neither is better, and neither asks you to degenerate.`)}),e.jsx("p",{style:a,children:o("Depois do Ultra existe o Renascimento, para quem tem a conta completa: sua criatura vira ovo, volta a Rookie e os atributos zeram — em troca ela nasce mais funda e você escolhe a criatura, a escola e o elemento dela. Bits, cenários, sonhos, hábitos e dias completos continuam intactos. Acontece uma vez só.","After the Ultra comes Rebirth, for full accounts: your creature becomes an egg, returns to Rookie and attributes reset — in exchange they are born deeper and you choose their creature, school and element. Bits, scenes, dreams, habits and complete days stay intact. It happens only once.")}),e.jsx("p",{style:a,children:o("Dias completos só acumulam. A evolução é sua: toque no Soulmon na página de Evolução para travar ou destravar o cadeado.","Complete days only accumulate. Evolution is yours to trigger: tap your Soulmon on the Evolution page to lock or unlock the padlock.")}),e.jsx("p",{style:a,children:o("Quando a barra enche, a próxima forma começa a tomar corpo: leva um tempo até ficar pronta. Volte quando quiser — ela espera por você, e nada se perde no caminho.","When the bar fills, the next form starts taking shape: it takes a while to be ready. Come back whenever you like — it waits for you, and nothing is lost along the way.")})]})},{id:"hearts",title:o("Corações","Hearts"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:a,children:o(`Na virada do dia você perde no máximo ${g} coração, proporcional ao que ficou por fazer. Cumpriu a meta, não perde nada.`,`At the day turn you lose at most ${g} heart, in proportion to what you left undone. Meet the goal and you lose nothing.`)}),e.jsx("p",{style:a,children:o(`Sumiu por ${v} dias ou mais? Voltar não custa nada. Toda segunda seu Soulmon recupera ${f} coração.`,`Away for ${v} days or more? Coming back costs nothing. Every Monday it recovers ${f} of a heart.`)}),e.jsx("p",{style:a,children:o("Cocô não limpo drena 1 coração a cada 6 horas — dê banho. Esfregar o pet é o principal jeito de curar (até 1 coração por dia). Se zerar, seu Soulmon regride uma forma.","Uncleaned poop drains 1 heart every 6 hours — give it a bath. Rubbing your pet is the main way to heal (up to 1 heart a day). At zero it degenerates one form.")})]})},{id:"care",title:o("Comida e energia","Food and energy"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:a,children:o(`As barras de energia são o requisito do estágio (Rookie: ${s.rookie.required}). Ela enche só comendo e zera todo dia.`,`Energy bars equal your stage requirement (Rookie: ${s.rookie.required}). It fills only by feeding and resets daily.`)}),e.jsx("p",{style:a,children:o(`Cada tarefa concluída rende uma comida. Alimentar dá energia e pontos de atributo — que definem o galho da evolução — e NÃO cura coração. Até ${x} vezes por hora.`,`Each completed task yields one food. Feeding grants energy and attribute points — which steer your evolution branch — and does NOT heal hearts. Up to ${x} times an hour.`)})]})},{id:"habits",title:o("Hábitos","Habits"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:a,children:o(`Não existe sequência que zera. O que aparece é a constância: "${h} das últimas ${c}". Uma falta custa uma fatia, nunca tudo.`,`There is no streak that resets. What you see is consistency: "${h} of the last ${c}". A missed day costs a slice, never everything.`)}),e.jsx("p",{style:a,children:o(`A cada ${b} dias de boa constância você ganha um escudo (até ${j}). Ele é gasto sozinho no dia em que você falta — nada para lembrar de ativar.`,`Every ${b} days of good consistency you earn a shield (up to ${j}). It is spent automatically on a day you miss — nothing to remember to switch on.`)}),e.jsx("p",{style:a,children:o(`Uma falta não gera nada. Em ${E} seguidas, o pet oferece uma versão bem menor do hábito — aceitar já conta como feito. E o ícone amadurece até virar árvore em ${m} dias feitos, rendendo mais atributo.`,`One miss does nothing. At ${E} in a row, your pet offers a much smaller version of the habit — accepting counts as done. And the icon matures into a tree at ${m} days done, yielding more attribute.`)})]})},{id:"tasks",title:o("Tarefas","Tasks"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:a,children:o(`Toda tarefa tem um esforço: Rápida (1), Média (2) ou Projeto (3). A meta soma esforço, não itens — um Projeto vale três Rápidas. Passando de ${S} pontos no dia, o pet avisa. É aviso, nunca bloqueio.`,`Every task has an effort: Quick (1), Medium (2) or Project (3). The goal adds up effort, not items — one Project is worth three Quick ones. Past ${S} points in a day your pet says so. A heads-up, never a block.`)}),e.jsx("p",{style:a,children:o(`No check-in você escolhe até ${i} focos do dia; completar os ${i} rende o selo.`,`At check-in you pick up to ${i} focus tasks; completing all ${i} earns the seal.`)}),e.jsx("p",{style:a,children:o(`Parada há ${A} dias ela fica assombrada — e concluir uma assombrada dá bônus de alívio. Adiada ${T} vezes, o pet oferece dividir, encolher ou deixar pra lá.`,`Untouched for ${A} days it becomes haunted — and clearing a haunted task grants a relief bonus. Postponed ${T} times, your pet offers to split it, shrink it or let it go.`)}),e.jsx("p",{style:a,children:o('"Algum dia" é permissão formal para não fazer agora: não conta na meta e não assombra. "Deixar pra lá" é um fim honesto, com volta atrás.',`"Someday" is formal permission not to do it now: it doesn't count toward the goal and never haunts. "Let it go" is an honest ending, with an undo.`)})]})},{id:"rest",title:o("Descanso e sonhos","Rest and dreams"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:a,children:o(`Você escolhe a SUA janela de sono (padrão ${d.start}–${d.end}, com ${$} min de tolerância). O que conta é o gesto de deitar no horário — nunca a qualidade do seu sono.`,`You choose YOUR own sleep window (default ${d.start}–${d.end}, with ${$} min of grace). What counts is going to bed on time — never how well you slept.`)}),e.jsx("p",{style:a,children:o(`Sem nota de sono e sem castigo: noite sem registro é neutra. A leitura é quantas das últimas ${q} noites entraram na janela.`,`No sleep score and no penalty: an unlogged night is neutral. The reading is how many of the last ${q} nights landed inside the window.`)}),e.jsx("p",{style:a,children:o(`Cada noite na janela seu Soulmon SONHA, e o sonho é uma cena colecionável do próprio Soulmon — ${p} para descobrir. A raridade vem da regularidade, nunca de dormir mais.`,`Every night inside the window it DREAMS, and the dream is a collectible scene of itself — ${p} to discover. Rarity comes from regularity, never from sleeping longer.`)})]})},{id:"passeio",title:o("Passeio e Travessias","Stroll and Crossings"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:a,children:o("Na Exploração fica o Passeio: seu Soulmon sai todo dia e conta o que viu no relatório do fim do dia. Você escolhe para onde — casa ou uma região já aberta.","The Stroll lives in Exploration: your Soulmon heads out every day and tells you what it saw in the end-of-day report. You pick where — home, or a region that is already open.")}),e.jsx("p",{style:a,children:o("Travessias são opcionais: algo que você faz na sua vida, fora do app, sempre com uma versão pequena para fazer em casa. Ficam esperando o tempo que for, e trocar ou deixar pra lá não custa nada. Quando você conta que fez, a névoa de uma região se abre no passeio da noite seguinte.","Crossings are optional: something you do in your own life, outside the app, always with a small version you can do at home. They wait as long as you like, and swapping or letting one go costs nothing. Once you say you did it, the mist over a region clears on the next night's stroll.")}),e.jsx("p",{style:a,children:o("Nada disso mexe no seu Soulmon, na meta do dia, nos corações ou na evolução. E dá para esconder as Travessias na própria folha do Passeio.","None of it touches your Soulmon, the daily goal, hearts or evolution. You can also hide Crossings from the Stroll sheet itself.")})]})},{id:"guild",title:w(r,"guild.guide.titulo"),body:e.jsx("p",{style:a,children:w(r,"guild.guide.corpo")})},{id:"more",title:o("O resto, em uma linha cada","Everything else, one line each"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:a,children:o("Galhos: Poder, Harmonia e Benevolência — os requisitos são iguais nos três. No empate decide o seu ritmo de cuidado, e nenhum ritmo é melhor.","Branches: Power, Harmony and Benevolence — requirements are identical across all three. Ties are decided by your care rhythm, and no rhythm is better.")}),e.jsx("p",{style:a,children:o("Traço de nascimento: todo Soulmon nasce com um (veja em Estatísticas). Todos são positivos.","Birth trait: every Soulmon is born with one (see it in Stats). All of them are upsides.")}),e.jsx("p",{style:a,children:o("Masmorra e Torneio nunca cobram corações. Perder custa só a run.","Dungeon and Tournament never cost hearts. Losing only costs the run.")}),e.jsx("p",{style:a,children:o("No duelo do Torneio os pets lutam sozinhos. Você torce três vezes: toque quando o anel encostar no círculo. Torcer só ajuda; não torcer não atrapalha.","In a Tournament duel the pets fight on their own. You cheer three times: tap when the ring meets the circle. Cheering only helps; skipping never hurts.")}),e.jsx("p",{style:a,children:o("O check-in e o relatório do dia levam vinte segundos; o de domingo descreve a semana. Nada disso vira nota.","Check-in and the daily report take twenty seconds; Sunday describes the week. None of it becomes a score.")}),e.jsx("p",{style:a,children:o("Toda segunda e todo dia 1 vem um recomeço: zera as cobranças pendentes e não apaga nada do que você conquistou.","Every Monday and every 1st a fresh start is offered: pending nagging is cleared and nothing you earned is erased.")})]})}];return e.jsxs(U,{open:_,onClose:u,language:r,title:o("Guia","Guide"),maxWidth:520,footer:e.jsx("button",{type:"button",onClick:u,style:{...P("outline"),width:"100%"},children:o("Fechar","Close")}),children:[e.jsx("p",{style:l,children:o("Toque num assunto. Nada aqui é obrigatório saber para jogar.","Tap a topic. None of this is required knowledge to play.")}),e.jsx("div",{style:{display:"flex",flexDirection:"column"},children:O.map(t=>{const n=k===t.id;return e.jsxs("div",{children:[e.jsxs("button",{type:"button",onClick:()=>N(n?null:t.id),"aria-expanded":n,"aria-controls":`guide-${t.id}`,className:"sm2-conta-chap",children:[e.jsx("span",{style:{flex:1,minWidth:0},children:t.title}),e.jsx(F,{name:n?"expand_less":"expand_more",size:24,tone:n?"primary":"muted"})]}),n&&e.jsx("div",{id:`guide-${t.id}`,className:"sm2-conta-chapbody",children:t.body})]},t.id)})}),e.jsx("p",{style:l,children:o("Nos dias em que não der, seu Soulmon continua aqui.","On the days you can’t, it stays right here.")})]})}export{W as GuideModal};
